// TempServlet.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
public class TempServlet extends HttpServlet {
  protected void doGet(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    resp.setContentType("text/html;charset=UTF-8");
    PrintWriter out = resp.getWriter();
    out.println("<form action='temp' method='post'>");
    out.println("摄氏温度：<input name='c'>");
    out.println("<input type='submit' value='转换'>");
    out.println("</form>");
  }
  protected void doPost(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    resp.setContentType("text/html;charset=UTF-8");
    PrintWriter out = resp.getWriter();
    try {
      double c = Double.parseDouble(
          req.getParameter("c").trim());
      double f = c * 9 / 5 + 32;
      out.printf("%.1f℃ = %.1f℉", c, f);
    } catch (Exception e) {
      out.print("请输入数字");
    }
  }
}
<!-- web.xml（写在<web-app>中） -->
<servlet>
  <servlet-name>temp</servlet-name>
  <servlet-class>com.demo.TempServlet</servlet-class>
</servlet>
<servlet-mapping>
  <servlet-name>temp</servlet-name>
  <url-pattern>/temp</url-pattern>
</servlet-mapping>

