成绩：<jsp:getProperty name="s" property="score" />

// AdminServlet.java
package com.demo;
import java.io.*;
import javax.servlet.*;
import javax.servlet.http.*;
public class AdminServlet extends HttpServlet {
  private String user, pwd;
  public void init() throws ServletException {
    user = getInitParameter("user");
    pwd = getInitParameter("pwd");
  }
  protected void doPost(HttpServletRequest req,
      HttpServletResponse resp)
      throws ServletException, IOException {
    String u = req.getParameter("username");
    String p = req.getParameter("password");
    if (user.equals(u) && pwd.equals(p)) {
      req.getSession().setAttribute("admin", u);
      resp.sendRedirect(
          req.getContextPath() + "/admin.jsp");
    } else {
      req.setAttribute("msg", "账号或密码错误");
      req.getRequestDispatcher("/login.jsp")
          .forward(req, resp);
    }
  }
}
<!-- web.xml（写在<web-app>中） -->
<servlet>
  <servlet-name>admin</servlet-name>
  <servlet-class>com.demo.AdminServlet</servlet-class>
  <init-param><param-name>user</param-name>
    <param-value>admin</param-value></init-param>
  <init-param><param-name>pwd</param-name>
    <param-value>abc123</param-value></init-param>
</servlet>
<servlet-mapping>
  <servlet-name>admin</servlet-name>
  <url-pattern>/admin/login</url-pattern>
</servlet-mapping>
